-- The row feed (0106) for the knowledge the browser keeps in collections, and the statuses and tags every screen reads.
-- A tag on or off an item changes that item's row: the terms-only tag triggers of 0106 give way to ones for every kind the feed carries.
-- A migration that rebuilds one of these tables must make its triggers again.
CREATE TRIGGER `feed_characters_insert` AFTER INSERT ON `characters` BEGIN SELECT row_changed('characters', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_characters_update` AFTER UPDATE ON `characters` BEGIN SELECT row_changed('characters', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_characters_delete` AFTER DELETE ON `characters` BEGIN SELECT row_changed('characters', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_relationships_insert` AFTER INSERT ON `relationships` BEGIN SELECT row_changed('relationships', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_relationships_update` AFTER UPDATE ON `relationships` BEGIN SELECT row_changed('relationships', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_relationships_delete` AFTER DELETE ON `relationships` BEGIN SELECT row_changed('relationships', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speech_rules_insert` AFTER INSERT ON `speech_rules` BEGIN SELECT row_changed('speechRules', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speech_rules_update` AFTER UPDATE ON `speech_rules` BEGIN SELECT row_changed('speechRules', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speech_rules_delete` AFTER DELETE ON `speech_rules` BEGIN SELECT row_changed('speechRules', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_documents_insert` AFTER INSERT ON `documents` BEGIN SELECT row_changed('documents', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_documents_update` AFTER UPDATE ON `documents` BEGIN SELECT row_changed('documents', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_documents_delete` AFTER DELETE ON `documents` BEGIN SELECT row_changed('documents', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_tags_insert` AFTER INSERT ON `tags` BEGIN SELECT row_changed('tags', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_tags_update` AFTER UPDATE ON `tags` BEGIN SELECT row_changed('tags', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_tags_delete` AFTER DELETE ON `tags` BEGIN SELECT row_changed('tags', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_statuses_insert` AFTER INSERT ON `statuses` BEGIN SELECT row_changed('statuses', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_statuses_update` AFTER UPDATE ON `statuses` BEGIN SELECT row_changed('statuses', NEW.`id`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_statuses_delete` AFTER DELETE ON `statuses` BEGIN SELECT row_changed('statuses', OLD.`id`, 'delete', OLD.`project_id`); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS `feed_knowledge_tags_insert`;--> statement-breakpoint
DROP TRIGGER IF EXISTS `feed_knowledge_tags_update`;--> statement-breakpoint
DROP TRIGGER IF EXISTS `feed_knowledge_tags_delete`;--> statement-breakpoint
CREATE TRIGGER `feed_knowledge_tags_insert` AFTER INSERT ON `knowledge_tags` WHEN NEW.`kind` IN ('terms', 'characters', 'relationships', 'speechRules', 'documents') BEGIN SELECT row_changed(NEW.`kind`, NEW.`item_id`, 'upsert', (CASE NEW.`kind` WHEN 'terms' THEN (SELECT `project_id` FROM `terms` WHERE `id` = NEW.`item_id`) WHEN 'characters' THEN (SELECT `project_id` FROM `characters` WHERE `id` = NEW.`item_id`) WHEN 'relationships' THEN (SELECT `project_id` FROM `relationships` WHERE `id` = NEW.`item_id`) WHEN 'speechRules' THEN (SELECT `project_id` FROM `speech_rules` WHERE `id` = NEW.`item_id`) WHEN 'documents' THEN (SELECT `project_id` FROM `documents` WHERE `id` = NEW.`item_id`) END)); END;--> statement-breakpoint
CREATE TRIGGER `feed_knowledge_tags_update` AFTER UPDATE ON `knowledge_tags` WHEN NEW.`kind` IN ('terms', 'characters', 'relationships', 'speechRules', 'documents') BEGIN SELECT row_changed(NEW.`kind`, NEW.`item_id`, 'upsert', (CASE NEW.`kind` WHEN 'terms' THEN (SELECT `project_id` FROM `terms` WHERE `id` = NEW.`item_id`) WHEN 'characters' THEN (SELECT `project_id` FROM `characters` WHERE `id` = NEW.`item_id`) WHEN 'relationships' THEN (SELECT `project_id` FROM `relationships` WHERE `id` = NEW.`item_id`) WHEN 'speechRules' THEN (SELECT `project_id` FROM `speech_rules` WHERE `id` = NEW.`item_id`) WHEN 'documents' THEN (SELECT `project_id` FROM `documents` WHERE `id` = NEW.`item_id`) END)); END;--> statement-breakpoint
CREATE TRIGGER `feed_knowledge_tags_delete` AFTER DELETE ON `knowledge_tags` WHEN OLD.`kind` IN ('terms', 'characters', 'relationships', 'speechRules', 'documents') BEGIN SELECT row_changed(OLD.`kind`, OLD.`item_id`, 'upsert', (CASE OLD.`kind` WHEN 'terms' THEN (SELECT `project_id` FROM `terms` WHERE `id` = OLD.`item_id`) WHEN 'characters' THEN (SELECT `project_id` FROM `characters` WHERE `id` = OLD.`item_id`) WHEN 'relationships' THEN (SELECT `project_id` FROM `relationships` WHERE `id` = OLD.`item_id`) WHEN 'speechRules' THEN (SELECT `project_id` FROM `speech_rules` WHERE `id` = OLD.`item_id`) WHEN 'documents' THEN (SELECT `project_id` FROM `documents` WHERE `id` = OLD.`item_id`) END)); END;
